const jiraMapIssuesByRank = `-- name: JiraMapIssuesByRank :many
SELECT m.local_id FROM jira_import_map m JOIN issues i ON i.id = m.local_id
WHERE m.site = $1 AND m.kind = 'issue' AND m.project_id = $2
ORDER BY (m.data->>'rank') COLLATE "C" NULLS LAST, m.jira_id
`

type JiraMapIssuesByRankParams struct {
	Site      string
	ProjectID *uuid.UUID
}

// Imported issues of a project in Jira rank order (LexoRank strings sort bytewise).
func (q *Queries) JiraMapIssuesByRank(ctx context.Context, arg JiraMapIssuesByRankParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, jiraMapIssuesByRank, arg.Site, arg.ProjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var local_id uuid.UUID
		if err := rows.Scan(&local_id); err != nil {
			return nil, err
		}
		items = append(items, local_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

